import json
from typing import Optional, Literal

import pytest

from ...base.client import BaseClient


class MessagesMethods(BaseClient):
    """
    Методы группы 'Сообщения' из https://im-docs.corp.mail.ru/
    """

    async def wim_im_sendIM(
        self,
        t: str,
        message: Optional[str] = None,
        notifyDelivery: Literal["true", "false"] = "true",
        offlineIM: int = 1,
        parts: Optional[list[dict]] = None,
        smartReplyMeta: Optional[list[dict]] = None,
        updateMsgId: Optional[int] = None,
        draftDeleteTime: Optional[int] = None,
        schedule: Optional[dict[str, int]] = None,
    ) -> dict:
        """
        :param t:Уникальный идентификатор пользователя или чата внутри сервиса,
         которому отправляем сообщение.
        :param message: Поле для отправки текста,
        ссылки на стикер, ссылки, эмодзи
        :param notifyDelivery: Нотификация о доставке
        :param offlineIM: Доставка сообщения если пользовать не в сети
        :param parts: Массив parts — это составные части,
        из которых состоит отправляемое сообщение.
        Параметр используется для ответов на другие сообщения,
        пересылки сообщений, а так же отправки медиа-объектов,
        опросов, контактов, местоположения и т. д.
        :param smartReplyMeta: Поле нужно для подсчёта статистики
        использования функции умных ответов.
        :param updateMsgId:
        :return: тело ответа сервера
        """
        self.sub_chats.add(t)

        data = {
            "aimsid": self.aimsid,
            "r": self.getReqId(),
            "t": t,
            "notifyDelivery": notifyDelivery,
            "offlineIM": offlineIM,
            "smartReplyMeta": [] if smartReplyMeta is None else smartReplyMeta,
            "updateMsgId": updateMsgId,
        }

        if draftDeleteTime is not None:
            data["draftDeleteTime"] = draftDeleteTime

        if parts:
            data["parts"] = json.dumps(parts)
        else:
            data["message"] = message

        if schedule is not None and self.api_ver < 118:
            pytest.skip("Scheduled msg is possible only in API version above 117")
        elif schedule is not None and self.api_ver >= 118:
            data["schedule"] = json.dumps(schedule)

        return await self.post("wim/im/sendIM", data=data)

    async def wim_im_setTyping(self, t: str, typingStatus: Optional[str] = "looking") -> dict:
        """
        Отправка статуса тайпинга/лукинга
        :param t: Уникальный идентификатор пользователя внутри сервиса,
        в диалоге с которым отправляем статус тайпинга/лукинга
        :param typingStatus: Текущий статус тайпинга/лукинга (typing, looking, none)
        :return: тело ответа сервера
        """
        return await self.post(
            "wim/im/setTyping",
            data={
                "aimsid": self.aimsid,
                "r": self.getReqId(),
                "t": t,
                "typingStatus": typingStatus,
            },
        )
